export function calculateWellDepth(waterLevelMeters: number): number {
  // User directive: well depth = water level + 3.5m + 0.8m
  return Number((waterLevelMeters + 3.5 + 0.8).toFixed(2));
}

export function getStationVulnerabilityScore(stationRisk: number): number {
  // User scale: above 70 is low vulnerability, 40-70 is moderate, below that is high
  return Math.max(0, Math.min(100, Math.round(100 - stationRisk)));
}

export function getStationRiskCategory(stationRisk: number): {
  score: number;
  label: string;
  tier: 'low' | 'moderate' | 'high';
  bg: string;
  text: string;
  border: string;
  desc: string;
} {
  const score = getStationVulnerabilityScore(stationRisk);

  if (score > 70) {
    return {
      score,
      label: "Low Vulnerability",
      tier: "low",
      bg: "bg-emerald-50 dark:bg-emerald-950/40",
      text: "text-emerald-700 dark:text-emerald-300",
      border: "border-emerald-200 dark:border-emerald-800/60",
      desc: "Water table depth is shallow with strong annual recharge. Low vulnerability to seasonal well dry-up."
    };
  } else if (score >= 40) {
    return {
      score,
      label: "Moderate Vulnerability",
      tier: "moderate",
      bg: "bg-amber-50 dark:bg-amber-950/40",
      text: "text-amber-700 dark:text-amber-300",
      border: "border-amber-200 dark:border-amber-800/60",
      desc: "Seasonal fluctuation observed during summer pre-monsoon months. Casing and screen placement require attention."
    };
  } else {
    return {
      score,
      label: "High Vulnerability",
      tier: "high",
      bg: "bg-rose-50 dark:bg-rose-950/40",
      text: "text-rose-700 dark:text-rose-300",
      border: "border-rose-200 dark:border-rose-800/60",
      desc: "Significant pre-monsoon drawdown or deep piezometric level. High vulnerability; rotary drilling to deep aquifer recommended."
    };
  }
}

export function calculateDistanceKm(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371; // Earth's radius in km
  const dLat = (lat2 - lat1) * (Math.PI / 180);
  const dLon = (lon2 - lon1) * (Math.PI / 180);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * (Math.PI / 180)) *
      Math.cos(lat2 * (Math.PI / 180)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c * 10) / 10;
}
